"use client";

import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { SparklesIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { AttachmentChip, type Attachment } from "./ai-composer/attachment-chip";
import {
  COMMANDS,
  DICTATION,
  MENTIONS,
  type MenuOption,
  replyFor,
  SUGGESTIONS,
} from "./ai-composer/data";
import { findTrigger, type Trigger } from "./ai-composer/find-trigger";
import { ModelMenu } from "./ai-composer/model-menu";
import { OptionList, optionId } from "./ai-composer/option-list";
import { SendButton } from "./ai-composer/send-button";
import { ToggleChip } from "./ai-composer/toggle-chip";
import { BulbIcon, MicIcon, PaperclipIcon, WebIcon } from "./icons";
import { words } from "./shared/answer";
import type { Effort } from "./shared/models";
import { StreamText } from "./shared/stream-text";
import { useWordStream } from "./shared/use-word-stream";

/**
 * The prompt box of an assistant: type, attach files, switch web search and
 * extended thinking, pick a model and effort, dictate, and send. A slash at
 * the start of a line lists commands and an at sign lists people to mention.
 */
export function AiComposer({ className }: { className?: string }) {
  const titleId = useId();
  const listId = useId();
  const field = useRef<HTMLTextAreaElement>(null);
  const fileInput = useRef<HTMLInputElement>(null);
  const [text, setText] = useState("");
  const [trigger, setTrigger] = useState<Trigger | null>(null);
  const [active, setActive] = useState(0);
  const [web, setWeb] = useState(false);
  const [think, setThink] = useState(true);
  const [modelId, setModelId] = useState("juniper-3");
  const [effort, setEffort] = useState<Effort>("medium");
  const [files, setFiles] = useState<Attachment[]>([]);
  const [listening, setListening] = useState(false);
  const [sent, setSent] = useState<{ prompt: string; reply: string } | null>(
    null,
  );
  const stream = useWordStream({ delay: 400 });
  const nextFile = useRef(0);

  const query = trigger?.query.toLowerCase() ?? "";
  const options = trigger
    ? (trigger.type === "command" ? COMMANDS : MENTIONS).filter((option) =>
        option.insert.toLowerCase().includes(query),
      )
    : [];
  const menuOpen = trigger !== null;

  // Uploads tick forward until each file is ready. The interval stops when nothing is left to upload.
  const uploading = files.some((file) => file.progress < 100);
  useEffect(() => {
    if (!uploading) return;
    const timer = setInterval(
      () =>
        setFiles((list) =>
          list.map((file) => ({
            ...file,
            progress: Math.min(100, file.progress + 12),
          })),
        ),
      120,
    );
    return () => clearInterval(timer);
  }, [uploading]);

  // Dictation adds the sample words after a short listen.
  useEffect(() => {
    if (!listening) return;
    const timer = setTimeout(() => {
      setText(
        (value) =>
          `${value}${value && !value.endsWith(" ") ? " " : ""}${DICTATION}`,
      );
      setListening(false);
    }, 1600);
    return () => clearTimeout(timer);
  }, [listening]);

  const readTrigger = (value: string) => {
    const caret = field.current?.selectionStart ?? value.length;
    const next = findTrigger(value, caret);
    setTrigger(next);
    if (next?.type !== trigger?.type || next?.query !== trigger?.query)
      setActive(0);
  };

  const choose = (option: MenuOption) => {
    if (!trigger) return;
    const caret = field.current?.selectionStart ?? text.length;
    const next =
      text.slice(0, trigger.from) + option.insert + text.slice(caret);
    setText(next);
    setTrigger(null);
    const at = trigger.from + option.insert.length;
    requestAnimationFrame(() => field.current?.setSelectionRange(at, at));
  };

  const send = () => {
    const prompt = text.trim();
    if (!prompt || stream.busy) return;
    const reply = replyFor(prompt, web, think);
    setSent({ prompt, reply });
    setText("");
    setTrigger(null);
    setFiles([]);
    stream.start(words(reply).length);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (menuOpen) {
      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        const step = event.key === "ArrowDown" ? 1 : -1;
        setActive((index) =>
          options.length ? (index + step + options.length) % options.length : 0,
        );
        return;
      }
      if ((event.key === "Enter" || event.key === "Tab") && options[active]) {
        event.preventDefault();
        choose(options[active]);
        return;
      }
      if (event.key === "Escape") {
        event.preventDefault();
        setTrigger(null);
        return;
      }
    }
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      send();
    } else if (event.key === "Escape" && stream.busy) {
      event.preventDefault();
      stream.stop();
    }
  };

  const total = sent ? words(sent.reply).length : 1;
  const progress =
    stream.status === "streaming"
      ? stream.shown / total
      : stream.status === "waiting"
        ? 0.04
        : 1;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div className="mx-auto flex max-w-2xl flex-col gap-5 px-4 py-8 @md:px-6 @md:py-10">
        <h2
          id={titleId}
          className="flex items-center justify-center gap-2 text-center text-xl font-semibold tracking-tight"
        >
          <SparklesIcon aria-hidden="true" className="size-5 text-chart-2" />
          What should Fern help with today?
        </h2>

        <div className="relative">
          <div className="flex flex-col gap-2">
            {files.length ? (
              <ul
                aria-label="Attached files"
                className="flex flex-wrap gap-1.5 px-1 pt-1"
              >
                {files.map((file) => (
                  <AttachmentChip
                    key={file.id}
                    file={file}
                    onRemove={() =>
                      setFiles((list) =>
                        list.filter((item) => item.id !== file.id),
                      )
                    }
                  />
                ))}
              </ul>
            ) : null}
            <Textarea
              ref={field}
              role="combobox"
              aria-label="Message Fern"
              aria-expanded={menuOpen}
              aria-controls={menuOpen ? listId : undefined}
              aria-autocomplete="list"
              aria-activedescendant={
                menuOpen && options[active]
                  ? optionId(listId, options[active])
                  : undefined
              }
              placeholder="Ask anything. Type / for commands or @ to mention someone"
              value={text}
              rows={2}
              onChange={(event) => {
                setText(event.target.value);
                readTrigger(event.target.value);
              }}
              onSelect={() => readTrigger(text)}
              onBlur={() => setTrigger(null)}
              onKeyDown={onKeyDown}
              className="max-h-48 min-h-14 resize-none"
            />
            <div className="flex flex-wrap items-center gap-1">
              <Input
                ref={fileInput}
                type="file"
                multiple
                className="sr-only"
                tabIndex={-1}
                aria-hidden="true"
                onChange={(event) => {
                  const picked = [...(event.target.files ?? [])].map(
                    (file) => ({
                      id: nextFile.current++,
                      name: file.name,
                      progress: 0,
                    }),
                  );
                  setFiles((list) => [...list, ...picked]);
                  event.target.value = "";
                }}
              />
              <Button
                variant="ghost"
                size="icon"
                className="size-8"
                aria-label="Attach files"
                onClick={() => fileInput.current?.click()}
              >
                <PaperclipIcon aria-hidden="true" className="size-4" />
              </Button>
              <ToggleChip
                pressed={web}
                onPressedChange={setWeb}
                label="Web search"
                icon={
                  <WebIcon
                    aria-hidden="true"
                    className={cn("size-4", web && "text-chart-2")}
                  />
                }
              />
              <ToggleChip
                pressed={think}
                onPressedChange={setThink}
                label="Extended thinking"
                icon={
                  <BulbIcon
                    aria-hidden="true"
                    className={cn("size-4", think && "text-chart-4")}
                  />
                }
              />
              <span className="flex-1" />
              <ModelMenu
                modelId={modelId}
                effort={effort}
                onModel={setModelId}
                onEffort={setEffort}
              />
              <Button
                variant={listening ? "secondary" : "ghost"}
                size="icon"
                className="size-8"
                aria-label={listening ? "Listening, tap to stop" : "Dictate"}
                aria-pressed={listening}
                onClick={() => setListening((value) => !value)}
              >
                <MicIcon
                  aria-hidden="true"
                  className={cn(
                    "size-4",
                    listening && "text-chart-5 motion-safe:animate-pulse",
                  )}
                />
              </Button>
              <SendButton
                busy={stream.busy}
                progress={progress}
                disabled={!text.trim()}
                onSend={send}
                onStop={stream.stop}
              />
            </div>
          </div>
          {menuOpen ? (
            <div className="absolute inset-x-2 top-full z-20 mt-1">
              <OptionList
                id={listId}
                label={
                  trigger.type === "command" ? "Commands" : "People and places"
                }
                options={options}
                active={active}
                onActive={setActive}
                onChoose={choose}
              />
            </div>
          ) : null}
        </div>

        <p className="sr-only" aria-live="polite">
          {listening
            ? "Listening"
            : stream.status === "done"
              ? "Reply ready"
              : ""}
        </p>

        {sent ? (
          <section
            aria-label="Latest reply"
            className="flex flex-col gap-2 rounded-2xl border border-border p-4 text-sm"
          >
            <p className="font-medium">{sent.prompt}</p>
            <p className="flex gap-2 leading-relaxed">
              {/* A box one text line tall centres the icon on the first line, with no nudge. */}
              <span className="flex h-5 shrink-0 items-center">
                <SparklesIcon
                  aria-hidden="true"
                  className="size-4 shrink-0 text-chart-2"
                />
              </span>
              <span>
                {stream.status === "waiting" ? (
                  <span className="motion-safe:animate-pulse">Thinking</span>
                ) : null}
                <StreamText
                  text={sent.reply}
                  start={0}
                  shown={stream.shown}
                  live
                />
                {stream.status === "stopped" ? (
                  <span className="text-xs text-muted-foreground">
                    You stopped this reply.
                  </span>
                ) : null}
              </span>
            </p>
          </section>
        ) : null}

        <ul
          aria-label="Suggested prompts"
          className="flex flex-wrap justify-center gap-2"
        >
          {SUGGESTIONS.map((suggestion) => (
            <li key={suggestion}>
              <Button
                variant="outline"
                size="sm"
                className="h-auto whitespace-normal"
                onClick={() => {
                  setText(suggestion);
                  field.current?.focus();
                }}
              >
                {suggestion}
              </Button>
            </li>
          ))}
        </ul>
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

