import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { XIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";

import { FileIcon } from "../icons";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** One file the person attached, with how far its upload has got. */
export interface Attachment {
  id: number;
  name: string;
  /** From 0 to 100. */
  progress: number;
}

/** A chip for one attached file. A thin bar fills while it uploads; the cross removes it. */
export function AttachmentChip({
  file,
  onRemove,
}: {
  file: Attachment;
  onRemove: () => void;
}) {
  const done = file.progress >= 100;
  const barStyle: VarStyle = { "--w": `${file.progress}%` };
  return (
    <li className="relative flex max-w-56 items-center gap-2 overflow-hidden rounded-lg border border-border bg-background py-1 pr-1 pl-2 text-xs">
      <FileIcon aria-hidden="true" className="size-4 shrink-0 text-chart-1" />
      <span className="min-w-0 flex-1 truncate">{file.name}</span>
      <span className="shrink-0 text-muted-foreground tabular-nums">
        {done ? "Ready" : `${file.progress}%`}
      </span>
      <Button
        variant="ghost"
        size="icon"
        className="size-6 shrink-0"
        aria-label={`Remove ${file.name}`}
        onClick={onRemove}
      >
        <XIcon aria-hidden="true" className="size-3" />
      </Button>
      {done ? null : (
        <span
          aria-hidden="true"
          className="absolute inset-x-0 bottom-0 h-0.5 bg-muted"
        >
          <span
            className="block h-full w-(--w) bg-chart-1 motion-safe:transition-all"
            style={barStyle}
          />
        </span>
      )}
    </li>
  );
}

