import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

/** One row of the slash or mention list. */
export interface MenuOption {
  id: string;
  label: string;
  hint: string;
  /** The text that replaces the typed trigger. */
  insert: string;
}

/** The slash commands. */
export const COMMANDS: MenuOption[] = [
  {
    id: "summarise",
    label: "/summarise",
    hint: "Sum up a patient's last visits",
    insert: "/summarise ",
  },
  {
    id: "draft",
    label: "/draft",
    hint: "Write a message to a patient",
    insert: "/draft ",
  },
  {
    id: "reschedule",
    label: "/reschedule",
    hint: "Find a new time for a booking",
    insert: "/reschedule ",
  },
  {
    id: "report",
    label: "/report",
    hint: "Build a report from clinic data",
    insert: "/report ",
  },
