/** A slash or at sign the person is typing after, with the text typed since. */
export interface Trigger {
  type: "command" | "mention";
  query: string;
  /** Where the trigger character sits in the text. */
  from: number;
}

/**
 * Reads the text before the caret. A slash counts only at the start of a
 * line; an at sign counts at the start or after a space.
 */
export function findTrigger(text: string, caret: number): Trigger | null {
  const before = text.slice(0, caret);
  const command = /(^|\n)\/(\w*)$/.exec(before);
  if (command)
    return {
      type: "command",
      query: command[2]!,
      from: caret - command[2]!.length - 1,
    };
  const mention = /(^|\s)@(\w*)$/.exec(before);
  if (mention)
    return {
      type: "mention",
      query: mention[2]!,
      from: caret - mention[2]!.length - 1,
    };
  return null;
}

